// IPA chart and phoneme workbench for Voxanth. No JS synthesis or npm.
// All audio is generated by crates/voxanth-core/src/ipa.rs via the
// standalone voxanth-web-audio WASM module.
(() => {
  "use strict";
  const $ = id => document.getElementById(id);
  const lab = $("ipa-lab");
  if (!lab) return;

  // Standard basic IPA vowel inventory (28 monophthongs).
  // Each row is ordered front / central / back; paired cells are
  // unrounded / rounded in that order.
  const vowelRows = [
    { height: "Close", positions: [["i", "y"], ["ɨ", "ʉ"], ["ɯ", "u"]] },
    { height: "Near-close", positions: [["ɪ", "ʏ"], [], ["ʊ"]] },
    { height: "Close-mid", positions: [["e", "ø"], ["ɘ", "ɵ"], ["ɤ", "o"]] },
    { height: "Mid", positions: [[], ["ə"], []] },
    { height: "Open-mid", positions: [["ɛ", "œ"], ["ɜ", "ɞ"], ["ʌ", "ɔ"]] },
    { height: "Near-open", positions: [["æ"], ["ɐ"], []] },
    { height: "Open", positions: [["a", "ɶ"], [], ["ɑ", "ɒ"]] }
  ];
  const playableConsonants = [
    { name: "Plosives", symbols: ["p", "b", "t", "d", "k", "ɡ"] },
    { name: "Nasals", symbols: ["m", "n", "ŋ"] },
    { name: "Fricatives", symbols: ["f", "v", "θ", "ð", "s", "z", "ʃ", "ʒ", "h"] },
    { name: "Approximants", symbols: ["ɹ", "j", "w", "l"] },
    { name: "Affricates", symbols: ["tʃ", "dʒ"] }
  ];
  const unmodeledConsonants = [
    { name: "Other plosives", symbols: ["ʈ", "ɖ", "c", "ɟ", "q", "ɢ", "ʔ"] },
    { name: "Other nasals", symbols: ["ɱ", "ɳ", "ɲ", "ɴ"] },
    { name: "Trills", symbols: ["ʙ", "r", "ʀ"] },
    { name: "Taps and flaps", symbols: ["ⱱ", "ɾ", "ɽ"] },
    { name: "Other fricatives", symbols: ["ɸ", "β", "ʂ", "ʐ", "ç", "ʝ", "x", "ɣ", "χ", "ʁ", "ħ", "ʕ", "ɦ"] },
    { name: "Lateral fricatives", symbols: ["ɬ", "ɮ"] },
    { name: "Other approximants", symbols: ["ʋ", "ɻ", "ɰ"] },
    { name: "Other lateral approximants", symbols: ["ɭ", "ʎ", "ʟ"] }
  ];

  const stockProfiles = [
    { name: "Clarity / speech", pitch_hz: 150, formant_scale: 1.04, breathiness: .06, brightness: .65, nasality: .08, vibrato: 0, speed: 1 },
    { name: "Ember / warm", pitch_hz: 112, formant_scale: .83, breathiness: .11, brightness: .34, nasality: .12, vibrato: .08, speed: .9 },
    { name: "Glass / bright", pitch_hz: 230, formant_scale: 1.28, breathiness: .18, brightness: .9, nasality: .03, vibrato: .07, speed: 1.1 },
    { name: "Aether / synthetic", pitch_hz: 195, formant_scale: .94, breathiness: .3, brightness: .72, nasality: .35, vibrato: .42, speed: .95 }
  ];
  const allVowels = vowelRows.flatMap(r => r.positions.flat());
  const allConsonants = playableConsonants.flatMap(group => group.symbols);
  const supported = new Set([...allVowels, ...allConsonants]);
  let audioSource = null;
  let audioSamples = null;

  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function selectedSymbol(symbol, name) {
    $("ipa-selection").textContent = "Selected: /" + symbol + "/ · " + name;
  }

  function appendSymbol(symbol) {
    const input = $("ipa-input");
    const start = input.selectionStart ?? input.value.length;
    const end = input.selectionEnd ?? input.value.length;
    input.setRangeText(symbol, start, end, "end");
  }

  function currentProfile() {
    let profile;
    try { profile = JSON.parse($("ipa-voice").value); }
    catch (_) { profile = stockProfiles[0]; }
    return {
      ...profile,
      pitch_hz: Number($("ipa-pitch").value),
      speed: Number($("ipa-speed").value)
    };
  }

  function render(text) {
    const synth = window.voxanthIpaRender;
    if (typeof synth !== "function") {
      throw new Error("The Rust IPA engine is not ready. The soundboard needs the independent WASM module.");
    }
    const p = currentProfile();
    const result = synth(text, p.pitch_hz, p.formant_scale, p.brightness,
      p.breathiness, p.nasality, p.vibrato, p.speed);
    if (!result || !result.length) throw new Error("Enter at least one IPA sound.");
    return result;
  }

  async function play(audio) {
    const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextConstructor) throw new Error("Web Audio is not supported.");
    const ctx = window.__voxanthAudio ||= new AudioContextConstructor();
    if (ctx.state === "suspended") await ctx.resume();
    if (audioSource) {
      try { audioSource.stop(); } catch (_) {}
      audioSource.disconnect();
    }
    const rate = window.voxanthAudioRate || 44100;
    const buffer = ctx.createBuffer(1, audio.length, rate);
    buffer.copyToChannel(new Float32Array(audio), 0);
    audioSource = ctx.createBufferSource();
    audioSource.buffer = buffer;
    audioSource.connect(ctx.destination);
    audioSource.start();
    audioSamples = audio;
    $("ipa-export").disabled = false;
  }

  function showError(error) {
    const reason = typeof error === "string" ? error : String(error?.message || error);
    $("ipa-status").textContent = "Cannot pronounce: " + reason;
    $("ipa-status").dataset.state = "error";
  }

  function showSuccess(text, audio) {
    $("ipa-status").textContent = "/" + text + "/ · " +
      (audio.length / (window.voxanthAudioRate || 44100)).toFixed(2) +
      "s of experimental Rust-synthesized audio.";
    $("ipa-status").dataset.state = "ready";
  }

  async function audition(symbol, label) {
    selectedSymbol(symbol, label);
    appendSymbol(symbol);
    try {
      const pcm = render(symbol);
      await play(pcm);
      showSuccess(symbol, pcm);
    } catch (error) { showError(error); }
  }

  function soundButton(symbol, name, enabled = true) {
    const button = element("button", "ipa-symbol", symbol);
    button.type = "button";
    button.dataset.symbol = symbol;
    button.title = name + (enabled ? " · click to hear and add" : " · not modeled yet");
    button.setAttribute("aria-label", symbol + ": " + name +
      (enabled ? ", synthesize and add to IPA sequence" : ", synthesis unavailable"));
    if (enabled) {
      button.addEventListener("click", () => {
        document.querySelectorAll(".ipa-symbol.active").forEach(b => b.classList.remove("active"));
        button.classList.add("active");
        audition(symbol, name);
      });
    } else {
      button.disabled = true;
      button.classList.add("not-modeled");
    }
    return button;
  }

  const positions = ["front", "central", "back"];
  const vowelGrid = $("ipa-vowel-grid");
  for (const row of vowelRows) {
    const label = element("div", "ipa-vowel-height", row.height);
    vowelGrid.append(label);
    row.positions.forEach((sounds, index) => {
      const cell = element("div", "ipa-vowel-cell");
      const position = positions[index];
      if (sounds.length === 0) cell.classList.add("empty");
      sounds.forEach((symbol, indexInCell) => {
        const rounded = sounds.length === 2 ? indexInCell === 1 :
          ["ʊ", "ʏ"].includes(symbol);
        const description = row.height.toLowerCase() + " " + position +
          (rounded ? " rounded" : " unrounded") + " vowel";
        cell.append(soundButton(symbol, description));
      });
      vowelGrid.append(cell);
    });
  }

  const consonantGrid = $("ipa-consonant-grid");
  for (const group of playableConsonants) {
    const card = element("section", "ipa-consonant-group");
    const header = element("h5", "", group.name);
    const buttons = element("div", "ipa-consonant-buttons");
    group.symbols.forEach(symbol => buttons.append(
      soundButton(symbol, group.name.toLowerCase() + " · early acoustic approximation")
    ));
    card.append(header, buttons);
    consonantGrid.append(card);
  }

  const unmodeledGrid = $("ipa-unsupported-grid");
  for (const group of unmodeledConsonants) {
    const section = element("section", "ipa-unmodeled-group");
    section.append(element("h5", "", group.name));
    const buttons = element("div", "ipa-consonant-buttons");
    group.symbols.forEach(symbol => buttons.append(
      soundButton(symbol, group.name.toLowerCase(), false)
    ));
    section.append(buttons);
    unmodeledGrid.append(section);
  }

  function chooseTab(tab) {
    const consonants = tab === "consonants";
    $("ipa-panel-vowels").hidden = consonants;
    $("ipa-panel-consonants").hidden = !consonants;
    for (const [name, selected] of [["vowels", !consonants], ["consonants", consonants]]) {
      const button = $("ipa-tab-" + name);
      button.setAttribute("aria-selected", String(selected));
      button.classList.toggle("selected", selected);
    }
  }
  $("ipa-tab-vowels").addEventListener("click", () => chooseTab("vowels"));
  $("ipa-tab-consonants").addEventListener("click", () => chooseTab("consonants"));

  function savedProfiles() {
    try {
      const value = JSON.parse(localStorage.getItem("voxanth-profiles-v1") || "[]");
      return Array.isArray(value) ? value.filter(p => p && typeof p.name === "string") : [];
    } catch (_) { return []; }
  }

  function refreshProfiles() {
    const select = $("ipa-voice");
    const previous = select.selectedOptions[0]?.textContent;
    select.replaceChildren();
    for (const [index, profile] of [...stockProfiles, ...savedProfiles()].entries()) {
      const option = element("option", "", profile.name);
      option.value = JSON.stringify(profile);
      if (previous ? profile.name === previous : index === 0) option.selected = true;
      select.append(option);
    }
  }
  function applyVoiceProfile() {
    const p = currentProfile();
    $("ipa-pitch").value = p.pitch_hz;
    $("ipa-speed").value = p.speed;
    updateSliders();
  }
  function updateSliders() {
    $("ipa-pitch-value").textContent = $("ipa-pitch").value + " Hz";
    $("ipa-speed-value").textContent = Number($("ipa-speed").value).toFixed(2) + "×";
  }
  $("ipa-voice").addEventListener("change", () => {
    const p = JSON.parse($("ipa-voice").value);
    $("ipa-pitch").value = p.pitch_hz;
    $("ipa-speed").value = p.speed;
    updateSliders();
  });
  $("ipa-pitch").addEventListener("input", updateSliders);
  $("ipa-speed").addEventListener("input", updateSliders);
  window.addEventListener("focus", refreshProfiles);
  window.addEventListener("storage", refreshProfiles);
  refreshProfiles();
  $("ipa-pitch").value = stockProfiles[0].pitch_hz;
  $("ipa-speed").value = stockProfiles[0].speed;
  updateSliders();

  $("ipa-play").addEventListener("click", async () => {
    try {
      const text = $("ipa-input").value.trim();
      const pcm = render(text);
      await play(pcm);
      showSuccess(text, pcm);
    } catch (error) { showError(error); }
  });
  $("ipa-try").addEventListener("click", () => {
    $("ipa-input").value = "hɛloʊ";
    $("ipa-input").focus();
    $("ipa-status").textContent = "English example ready: /hɛloʊ/. Click Pronounce IPA.";
  });
  $("ipa-clear").addEventListener("click", () => { $("ipa-input").value = ""; $("ipa-input").focus(); });
  $("ipa-backspace").addEventListener("click", () => {
    const input = $("ipa-input");
    const prefix = [...input.value];
    prefix.pop();
    input.value = prefix.join("");
    input.focus();
  });
  $("ipa-copy").addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText($("ipa-input").value);
      $("ipa-status").textContent = "IPA sequence copied.";
    } catch (error) { showError(error); }
  });
  $("ipa-export").addEventListener("click", () => {
    if (!audioSamples) return;
    const rate = window.voxanthAudioRate || 44100;
    const bytes = new ArrayBuffer(44 + audioSamples.length * 2);
    const view = new DataView(bytes);
    function write(offset, value) {
      for (let i = 0; i < value.length; i++) view.setUint8(offset + i, value.charCodeAt(i));
    }
    write(0, "RIFF"); view.setUint32(4, bytes.byteLength - 8, true);
    write(8, "WAVE"); write(12, "fmt "); view.setUint32(16, 16, true);
    view.setUint16(20, 1, true); view.setUint16(22, 1, true);
    view.setUint32(24, rate, true); view.setUint32(28, rate * 2, true);
    view.setUint16(32, 2, true); view.setUint16(34, 16, true);
    write(36, "data"); view.setUint32(40, audioSamples.length * 2, true);
    for (let i = 0; i < audioSamples.length; i++) {
      const n = Math.max(-1, Math.min(1, audioSamples[i]));
      view.setInt16(44 + 2 * i, Math.round(n * (n < 0 ? 32768 : 32767)), true);
    }
    const url = URL.createObjectURL(new Blob([bytes], { type: "audio/wav" }));
    const anchor = element("a");
    anchor.href = url; anchor.download = "voxanth-ipa.wav";
    document.body.append(anchor); anchor.click(); anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });

  function onEngineReady() {
    $("ipa-engine-pill").textContent = "● RUST AUDIO READY";
    $("ipa-engine-pill").classList.add("ready");
    $("ipa-status").textContent = "28 IPA vowels and 24 English consonants are available for experimental synthesis.";
    $("ipa-status").dataset.state = "ready";
    if (new URLSearchParams(location.search).has("ipa-smoke")) {
      try {
        if (allVowels.length !== 28 || allConsonants.length !== 24) throw new Error("IPA inventory changed");
        if ($("ipa-vowel-grid").querySelectorAll("button:not(:disabled)").length !== 28) {
          throw new Error("IPA vowel chart is incomplete");
        }
        for (const symbol of allVowels) {
          const pcm = window.voxanthIpaRender(symbol, 150, 1, .65, .06, .08, 0, 1);
          if (pcm.length < 6000 || !pcm.some(n => Math.abs(n) > .001)) throw new Error(symbol);
        }
        for (const symbol of allConsonants) {
          const pcm = window.voxanthIpaRender(symbol, 150, 1, .65, .06, .08, 0, 1);
          if (pcm.length < 4000 || !pcm.some(n => Math.abs(n) > .001)) throw new Error(symbol);
        }
        let rejected = false;
        try { window.voxanthIpaRender("ʙ", 150, 1, .65, .06, .08, 0, 1); }
        catch (_) { rejected = true; }
        if (!rejected) throw new Error("Unsupported consonant wasn't rejected");
        document.documentElement.dataset.ipaSmoke = "passed";
      } catch (error) {
        document.documentElement.dataset.ipaSmoke = "failed";
        console.error("[Voxanth IPA smoke test]", error);
      }
    }
  }

  window.addEventListener("VoxanthAudioReady", onEngineReady);
  window.addEventListener("VoxanthAudioError", event => {
    $("ipa-engine-pill").textContent = "AUDIO OFFLINE";
    showError(event.detail?.message || "The independent audio module could not load.");
  });
  if (typeof window.voxanthIpaRender === "function") onEngineReady();

  if (supported.size !== 52) console.error("Unexpected IPA inventory count:", supported.size);
})();
